        'Kopyalandı': 'Скопировано',
        'Kimlik panoya kopyalandı.': 'Идентификатор скопирован в буфер обмена.',
        'Tüm kimlik biçimleri panoya kopyalandı.': 'Все форматы идентификатора скопированы в буфер обмена.',
        'Aşağıdaki değerler bağlı hesabın kimliğidir. Hepsi aynı hesabı gösterir; ticaret siteleri, başarım araçları ve topluluk sayfaları farklı biçim ister. Satırın sonundaki düğme değeri panoya kopyalar.': 'Значения ниже - идентификатор подключённого аккаунта. Все они указывают на один и тот же аккаунт; сайтам обмена, инструментам достижений и страницам сообщества нужен разный формат. Кнопка в конце строки копирует значение в буфер обмена.',
        'Bu değerler gizli değildir; profilin herkese açık kimliğidir. Gizli olan tek şey oturum anahtarındır, o da settings klasöründe kalır.': 'Эти значения не секретны; это публичный идентификатор вашего профиля. Секретен только ключ сессии, и он остаётся в папке settings.',
