        'Detay: Gerçekçi': 'Подробности: реалистичный режим',
        'Detay: Başarım': 'Подробности: достижения',
        'Hepsi birden': 'Все сразу',
        'Eşitleme adımı # / #': 'Шаг выравнивания # / #',
        'Hepsi birden: seçili oyunların tamamı aynı anda çalışır, hedefe ulaşan listeden düşer. En hızlı yol budur. Sıralı: en geride kalan oyun tek başına öne çekilir, bir sonrakine yetişince ikisi birlikte devam eder; sırasını bekleyen oyun süre kazanmaz.': 'Все сразу: все выбранные игры работают одновременно, а достигшая цели уходит из списка. Это самый быстрый путь. По очереди: самая отстающая игра подтягивается в одиночку, а догнав следующую, они идут вместе; ждущая своей очереди игра часов не набирает.',
        'Gecikmiş başarımları hızlandır': 'Ускорить просроченные достижения',
