        'En fazla # preset tutulur. Önce birini sil.': 'Хранится не больше # пресетов. Сначала удалите один.',
        'Oyun saatlerce oynanmış ama başarım açılmamışsa arada bir birikim vardır. Açıkken bu birikim oturumun ilk beşte birinde hızlıca kapatılır, sonra ritim normale döner. Birikimin büyüklüğü oynanma süresine bağlıdır: bir saatlik oyunda birkaç başarım, yüz saatlik oyunda çok daha fazlası.': 'Если в игре наиграны часы, а достижения не открывались, накопилось отставание. При включённой настройке оно быстро закрывается в первой пятой части сессии, а затем ритм возвращается к обычному. Размер отставания зависит от наигранного времени: в часовой игре это пара достижений, в сточасовой - гораздо больше.',
        'Açıkken bir eşyanın en düşük fiyatı çekilirken gerçekleşen satış ortalaması da aynı turda çekilir; ortalama için listenin tamamının bitmesini beklemezsin. Öğe başına iki istek gittiği için envanterin tamamının dolması iki katı sürer. Kapalıyken ortalamalar yalnızca Envanter sayfasındaki Ortalama düğmesiyle gelir.': 'При включённой настройке средняя цена состоявшихся продаж запрашивается в том же проходе, что и минимальная цена, так что ждать конца всего списка не нужно. Поскольку на предмет уходит два запроса, весь инвентарь заполняется вдвое дольше. При выключенной настройке средние приходят только по кнопке «Средняя» на странице инвентаря.',
