        'Tüm çizelgeyi sıkar ya da açar. 0,5 iki katı hızlı.': 'Сжимает или растягивает весь график. 0,5 - вдвое быстрее.',
        '%5 altı başarımlar bu oranda daha uzun bekler.': 'Достижения реже 5% ждут во столько раз дольше.',
