        'Oynanan süre bitiş süresini geçtiyse çizelge bu orana iner.': 'Если наигранное время больше времени прохождения, график сжимается до этой доли.',
        'Süreyi ayarlara göre belirle': 'Определять длительность по настройкам',
        'Pencere gizliyken listeler bellekten düşer, geri gelince yeniden çizilir': 'Пока окно скрыто, списки освобождают память, а при возврате рисуются заново',
