        'Tahmini bitiş': 'Расчётное завершение',
        'Odak dışındayken çizimi durdur': 'Останавливать отрисовку без фокуса',
        'Pencere ekranda durup odakta değilken saniyelik güncellemeler ve dönen animasyonlar durur. Tam ekran bir oyunla aynı masaüstündeyken masaüstü birleştiricisi oyunun sunum yolunu serbest bırakır, kare hızı düşmez. Arka planda çalışan işler etkilenmez, yalnızca çizim durur.': 'Пока окно стоит на экране без фокуса, посекундные обновления и вращающиеся анимации останавливаются. Когда на том же рабочем столе идёт полноэкранная игра, диспетчер окон оставляет ей её путь вывода, и частота кадров не падает. Фоновые задачи не затрагиваются, останавливается только отрисовка.',
        'Grafik arka ucu': 'Графический бэкенд',
        'Chromium, arayüzü çizerken Windows üzerinde D3D11 kullanır. Bazı Intel ve eski AMD sürücülerinde bu yol takılıyor; D3D9 ya da OpenGL düzeltiyor. Otomatik, Chromium ne seçerse odur. Değiştirmek uygulamayı yeniden başlatmayı gerektirir.': 'Chromium рисует интерфейс через D3D11 на Windows. На некоторых драйверах Intel и старых AMD этот путь подвисает; D3D9 или OpenGL это исправляют. «Автоматически» - то, что выберет сам Chromium. Изменение требует перезапуска приложения.',
        'Otomatik': 'Автоматически',
        'GPU birleştirme': 'Композиция на GPU',
        'Kapalıyken pencerenin kareleri işlemcide birleştirilir, ekran kartına hiç dokunulmaz. Oyun oynarken ekran kartını tamamen serbest bırakır, karşılığında birkaç puan işlemci yer. Yeniden başlatmayı gerektirir.': 'При выключенной настройке кадры окна собираются на процессоре, видеокарта не задействуется вовсе. Во время игры она полностью остаётся вашей игре, ценой нескольких процентов процессора. Требует перезапуска.',
        'Görsel önbelleğini boşalt': 'Очистить кеш изображений',
        'Oyun kapak görselleri ve indirilen sayfa parçaları bellekten ve diskten silinir. Ayar, oturum ve istatistik kaybı yoktur; silinen her şey gerektiğinde yeniden indirilir. Uzun süre açık kalan oturumlarda belleği geri kazanmanın en doğrudan yolu.': 'Обложки игр и загруженные части страниц удаляются из памяти и с диска. Настройки, сессия и статистика не теряются; всё удалённое загрузится снова, когда понадобится. В долгих сессиях это самый прямой способ вернуть память.',
        'Boşalt': 'Очистить',
        'Önbellek boşaltılıyor...': 'Кеш очищается...',
        'Önbellek boşaltıldı.': 'Кеш очищен.',
        'Boşaltılamadı.': 'Очистить не удалось.',
        '# MB geri alındı.': 'Возвращено # МБ.',
        'Ayar kaydedildi': 'Настройка сохранена',
        'Etkili olması için SteamEdge yeniden başlatılmalı.': 'Чтобы изменение вступило в силу, SteamEdge нужно перезапустить.',
        '%100 Bitiş Süresi': 'Время прохождения на 100%',
        'Bu oyunu başarımlarıyla birlikte bitirmek kaç saat sürer. Ana hikayenin süresi değil, hepsini toplama süresi. Boş bırakırsan aşağıdaki oyun türünden tahmin edilir; ama o tahmin senin oynadığın süreye dayandığı için çok oynadığın oyunlarda şişer. Değer oyun başına hatırlanır.': 'Сколько часов нужно, чтобы пройти эту игру со всеми достижениями. Не длительность основного сюжета, а полное прохождение. Если оставить пустым, значение оценивается по типу игры ниже, но эта оценка опирается на ваше наигранное время и потому раздувается в играх, где вы провели много часов. Значение запоминается для каждой игры отдельно.',
